def can_make_zeros(a):
    n = len(a)
    if a.count(1) <= floor(n / 3):
        return "YES", 0

    operations = []
    count_ones = a.count(1)

    if count_ones == 0:
        return "YES", 0

    divisors = [i for i in range(1, count_ones + 1) if count_ones % i == 0]

    for d in divisors:
        if count_ones % d == 0:
            r = count_ones // d
            if 3 * (r - 1) + 3 <= n:
                for i in range(r - 1):
                    operations.append([d * i + 1, d * i + 2, d * i + 3])
                return "YES", len(operations)

    return "NO", len(operations)

