from collections import deque

def can_be_zeroized(n, a):
    if sum(a) % 2:
        return "NO"
    d = deque(a)
    operations = []

    while d or not operations:
        good_suffix = []
        for i in range(len(d) - 1, -1, -1):
            if d[i] == 1:
                good_suffix.append(i)
        if len(good_suffix) < 3:
            break

        least_g = max(good_suffix)
        mx_in_g = max(d[len(good_suffix):])
        if mx_in_g < least_g * 2:
            m = 3
        else:
            closest = d.index(min([mx_in_g, least_g * 2]))
            count = min(mx_in_g, least_g) // 2
            best = min(mx_in_g, least_g)
            m = count // best + 1
            good_suffix.clear()
            least_g = best

        for i in range(max(0, m - 2), max(len(d) - m + 1, 0), -1):
            if sum(d[i + j:i + m]) > 1:
                is_group = d[i:i + m].index(1) + 1
                if sum([d[j:i - 1], d[i + m:], d[j:i]]) > 1:
                    c = int((sum(d[i:i + m]) == m + best and len(set(d)) == m + 2) or (d[j + is_group:i - is_group].count(1) == 1 and sum(d[j:i + is_group]) < 3 * is_group))
                    if len(set(d[0:i + m])) == m + c:
                        good_suffix += [i + j for j in range(c, m, c)]
                        break
                    good_suffix.clear()
                    break

        ops_to_this = []
        for i in range(x := len(good_suffix) - 2, -1, -1):
            d.appendleft(d.pop())
            if 1 < sum(d[:x + 1]) < 2:
                ops_to_this.append(x + 1)
            if 1 < sum(d[x + 1: x + m]) < 2:
                y = x + m
                d.appendleft(d.pop())
                c = ((y - x) // (m * 2 - 2) - ((y - x) % (m * 2 - 2)) == m and 
                      y // ((m * 2 - 2) // (y - x)) and 
                      d[y : y + (m * 2 - 2) // (y - x)] and 
                      m * (y - x) + x - y > 1)
                if c:
                    if len(d[y:y + m * 2 - y]) == m * 2 - y:
                        bad_suffix = d[y:y + m * 2 - y] + d[y + m:y + m * 2 - y]
                        need_val = min(c, len(set(bad_suffix)))
                        ops_to_this.append(y - x * need_val)
                        ops_to_this.append(y + m - y * need_val)
                d.appendleft(d.pop())
                if m * (x - y) + x - y > 1:
                    ops_to_this.append(x + y  - x * m)

        for x in reversed(ops_to_this):
            d[x] = not d[x]
        if len(d) <= 2:
            m = 0
            if d:
                m = 3
            if not d:
                m += 3
            operations.append((m, *d[:len(d) // 2]))
    return "YES" if not operations else "NO"

