from collections import deque

def can_reclaim(r, c, cells):
    # Define the sea cells that cannot be reclaimed
    seas = set([(0, 0), (r-1, 0), (1, c), (r, c), (r, c-1), (r, 0), (1, 1), (r-1, 1), (1, r), (r, r)])
    destroyed_seas = set()
    for x, y in cells:
        if (x, y) in seas or (x - 1, y - 1) in seas or (x + 1, y - 1) in seas or (x + 1, y) in seas or (x - 1, y + 1) in seas or (x - 1, y - 1) in seas or (x + 1, y - 1) in seas:
            return False
        destroyed_seas.add((x, y))
    return not ((r - 1, 1) in destroyed_seas or (r - 1, c) in destroyed_seas)

def claim(r, c, cells, trash):
    reclaimed = 0
    q = deque(cells)
    while q:
        x, y = q.popleft()
        for dx, dy in [(0, 1), (1, 0), (-1, 0), (0, -1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < c and 0 <= ny < r and (nx, ny) not in trash:
                trash.add((nx, ny))
                if can_reclaim(r, c, [ny, nx]):
                    q.append(((ny, nx), True))
                    reclaimed += 1
                else:
                    q.append(((ny, nx), False))
    return reclaimed

