def min_characters_to_erasure(s, x):
    pfx = list()
    sum_remain = 0
    ans = len(s)

    def is_x_prime(f, s1, s2):
        if sum_remain == f:
            return True
        if sum_remain != f % f and (s1, s2) not in set(pfx):
            return False
        return False

    for i in range(len(s)):
        sum_remain += int(s[i])
        pfx.append((sum_remain, i))
        if len(pfx) > x:
            sum_remain -= int(s[pfx[-x][1]])
            pfx.pop()

    if sum_remain == x:
        ans = len(s) - 1
    elif sum_remain % x == 0 and sum_remain != x:
        ans = len(s) - 1

    for i in reversed(range(len(s))):
        sum_remain -= int(s[i])
        namespace = pfx.copy()
        if is_x_prime(sum_remain, min(i + 1, len(pfx) - 1), max(i - 1, 0)):
            continue
        for sub in namespace:
            if i >= sub[1] and sub[0] % sum_remain == x:
                ans = min(ans, len(s) - 1 - i)
                break

    return ans


