from collections import Counter

def lengthOfLongestSubarrayWithUniqueMostFrequentElement(n, nums):
    max_length, current_most_frequent, current_frequencies, all_frequencies = 0, 0, Counter(), set()
    last_occurrence = {}

    for i, num in enumerate(nums):
        if num in current_frequencies:
            all_frequencies.add(num)
            current_most_frequent = max(current_most_frequent, len(current_frequencies))
        else:
            current_frequencies[num] = nums.count(num)

        if i - len(all_frequencies) > n - 1 or len(all_frequencies) > n:
            current_frequencies[nums[i - (n - len(all_frequencies) - 1)]] -= nums[i - (n - len(all_frequencies) - 1)]
            current_frequencies.pop(nums[i - (n - len(all_frequencies) - 1)], None)

            if nums[i - (n - len(all_frequencies) - 1)] in all_frequencies:
                all_frequencies.remove(nums[i - (n - len(all_frequencies) - 1)])
            current_most_frequent = max(current_most_frequent, len(current_frequencies))

        if current_frequencies[num] not in last_occurrence:
            last_occurrence[current_frequencies[num]] = i

        max_length = max(max_length, i - last_occurrence[current_frequencies[num]])

    return max_length

