                steps[index] = 0
                continue
            current_elevation += 1
        else:
            right_steps.setdefault(current_elevation, len(right_steps)).append(index)
            if current_elevation == 0:
                left_steps.setdefault(current_elevation, [index]).reverse()
            elif steps[index] == 0:
                steps[index] = current_elevation
            else:
                right_steps[current_elevation + 1].append(index)

    back_steps = 0
    elevation = 0
    for i in range(len(footprints)):
        if steps[i] == -1:
            elevation += 1
        else:
            if elevation % 2 == steps[i] % 2 and elevation + 1 != steps[i] + 1:
                back_steps += 1
            elevation = steps[i]

