import math

def is_bitonic(arr):
    n = len(arr)
    if n <= 1:
        return False
    if arr == sorted(arr) or arr == sorted(arr, reverse=True):
        return True
    increasing, decreasing = [], []
    for i in range(1, n):
        if arr[i] >= arr[i-1]:
            increasing.append(arr[i-1])
        else:
            decreasing.append(arr[i-2])
        decreasing.append(arr[i])
    if increasing and decreasing:
        increasing.append(arr[-2])
    return all(arr == sorted(arr)) or increasing or decreasing

