    A substring s[l..r] is x-prime if f(l, r) = x and there are no values l2, r2 such that f(l2, r2) != x and x is divisible by f(l2, r2).
    """
    len_s = len(s)
    total = sum(map(int, s))
    prime = [False, False] + [True] * (9 * len_s - 1)
    prime[0], prime[1] = False, False  # 1 is not divisible by any number
    for i in range(2, int(total**0.5) + 1):
