def closest_letter(s):
    lookup = list(range(len(s)))  # For backtrack
    pos = {sym: i for i, sym in enumerate(s)}
    visited = set()
    for i in reversed(range(len(s))):
        successors = [pos[c] for c in s[i+1:i+1+len(i)] if i+1 < len(s) and s[i] != c]
        if not successors:
            if i < len(s)-1 and s[i] != s[i+1]:
                return i
            v = pos[s[i]]
            if v not in visited:
                if v == 0:
                    lookup[v] = sys.maxsize
                else:
                    _, lookup[v-1] = min((lookup[v-1], v+v-1), key=lambda x: x)
                visited.add(v)
            return v
    return -1

