def min_erased_chars(x, s):
    n = len(s)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            dp[i][j + 1] = min(dp[i][j + 1], dp[j][j] + min(dp[i - 1][1:], x - f(j + 1, i, s)))
            dp[i][j] = min(dp[i][j], dp[i - 1][j] + (x - f(s[i - 1] + s[i], s[i] + s[i]) + 1) if s[i] != s[i - 1] else dp[i - 1][j])
