import collections

def can_reach(x1, y1, x2, y2, grid):
    queue = collections.deque([(x1, y1, 0)])
    directions = {(0, 1), (1, 0)}
    visited = set([(x1, y1)])

    while queue:
        (x, y, steps) = queue.popleft()

        if (x, y) == (x2, y2):
            return True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '.':
                queue.append((nx, ny, steps + 1))
                visited.add((nx, ny))

    return False

