    max_row = [max(row_sum[i::size]) for i in range(size)]

    col_sum = [sum(values[j::size*size//size][i*size//size] for j in range(size)) for i in range(size)]
    max_col = [max(col_sum[i::size]) for i in range(size)]

    # Find elements in matrix
    for r in range(size):
        for c in range(size):
            value = values[r*size + c]
            if value not in values:
                return -1

    return max_row + max_col

