def walk_trail(sequence):
    footprint = '^'
    history = deque()
    count = 0
    for step in sequence:
        index = ord(step) - ord('A')
        if footprint == '^':
            if count % 2 == 1:  # Suppose the walk is starting with a right foot
                footprint = 'o'
                count += 1
            else:
                footprint = '>'
                count += 1
        else:  # Assume the walk is starting with a left foot
            if count % 2 == 1:  # Now the walk is corresponding to a count of 2
                footprint = '>'
            else:
                footprint = 'o'
                count += 1
        history.append(footprint)
    return ''.join(reversed(history))

