def find_median(numbers):
    if len(numbers) % 2 == 1:
        return numbers[len(numbers) // 2]
    else:
        return (numbers[len(numbers) // 2 - 1] + numbers[len(numbers) // 2]) / 2

def main(number_line, current_number_line, position):
    expected_column = min(position + 1, len(number_line)) - 1
    current_column = min(position + 1, len(current_number_line)) - 1
    if current_column > expected_column:
        left_surface = find_median(current_number_line[:position])
    else:
        left_surface = 0
    if current_column + 1 == expected_column:
        left_surface += find_median(number_line[position:])
    if current_column + 1 != expected_column:
        right_surface = find_median(current_number_line[position + 1:])
    else:
        right_surface = 0
    return left_surface + right_surface

def solution(number_line):
    number_line = list(number_line)
    position = len(number_line)
    for i in range(len(number_line) - 1, 0, -1):
        position -= main(number_line, number_line[i - 1:], i - 1)
    return position

