from collections import Counter

def count_predecessors(steps):
    predecessors = [-1] * len(steps)
    count = Counter(steps)

    stack = []

    for i, step in enumerate(steps):
        if step % 2 == 0:
            while stack and stack[-1] != 1:
                predecessors[stack.pop()] = 1
            if stack and stack[-1] == 1:
                predecessors[i] = 0
            else:
                predecessors[i] = 1
            stack.append(i)
        elif step % 2 == 1:
            while stack and stack[-1] != 2:
                predecessors[stack.pop()] = 2
            if stack and stack[-1] == 2:
                predecessors[i] = 1
            else:
                predecessors[i] = 2
            stack.append(i)

    return predecessors

def minimum_backward_steps(steps):
    predecessors = count_predecessors(steps)
    backward_steps = 0

    for i, step in enumerate(steps):
        if step % 2 == 0 and predecessors[i] == 1:
            backward_steps += 1
        elif step % 2 == 1 and predecessors[i] == 2:
            backward_steps += 1

    return backward_steps

