from collections import deque

def can_reclaim(r, c, grid, cell):
    # Check if the current cell can be reclaimed
    # Note: (0, 0) and (0, c-1) are adjacent
    if cell == (0, 0) or cell == (0, c-1) or grid[1][0][cell[1] - 1]:
        return False
    # Check if the current cell can be reclaimed
    # Note: (r-1, 0) and (r-1, c-1) are adjacent
    if cell == (r-1, 0) or cell == (r-1, c-1) or grid[r-1][c-1][cell[1] - 1]:
        return False
    return True

def count_reclaims(r, c, n, cells):
    grid = [defaultdict(lambda: defaultdict(bool)) for _ in range(n+2)]
    # Initialize grid with defaultdict for r(0), c(0) and r(r), c(c)
    # Also, we start from (1,1) and (r,r) so that leftmost and rightmost cells would be remembered
    # Here, each defaultdict will be a grid[row][col] with col corresponding to bottom sea cells
    for cell in cells:
        if can_reclaim(cell[0], cell[1], grid, cell):
            grid[cell[0]][cell[1]][cell[0]] = True
    queue = deque()
    # Initially, mosquito bites (sea cells) are placed (1,0), (r,r)
    for d in range(n-1, -1, -1):
        for k in range(c):
            if grid[r-1][k][d]:
                queue.append((k, 1)) 
            if grid[0][k][d]:
                queue.append((c-k-1, 0)) 
    rats = 0
    head = 0
    while queue:
        x, d = queue.popleft()
        if x == 0 and d == c:
            break
        rats += 1
        for k in range(c):
            if grid[r-1][k][d]:
                queue.append((c-k-1, 0)) 
            if grid[0][k][d]:
                queue.append((c+k, d+1)) 

    return rats

r, c, n = map(int, input().split())
cells = [list(map(int, input().split())) for _ in range(n)]
print(count_reclaims(r, c, n, cells))
