import sys

def find_min_backward_steps(footprints):
    forward_steps = 0
    backward_steps = 0

    for i in range(len(footprints) - 1):
        if footprints[i:i+2] in ["RL", "RRR"]:
            forward_steps += 1
        elif footprints[i:i+2] == "LL":
            backward_steps += 1

    return backward_steps

def generate_possible_history(footprints):
    possible_orders = []

    def backtrack(start, current_order):
        if start == len(footprints):
            possible_orders.append(current_order)
            return

        for i in range(start, len(footprints)):
            if footprints[start:i+1] in ["RL", "RRR"]:
                backtrack(i+1, current_order + [i])

    backtrack(0, [])

    return possible_orders

def main():
    footprints = sys.stdin.readline().strip()
    min_backward_steps = find_min_backward_steps(footprints)
    print(min_backward_steps)

    possible_history = generate_possible_history(footprints)
    print(" ".join(map(str, possible_history[0])))
    for i in range(1, len(possible_history)):
        print(" ".join(map(str, possible_history[i])))

if __name__ == "__main__":
    main()
