            left_bound = min(left_dist[l] for l in arr[k:])
            dists[k] = dist * left_bound
            dists[k + 1] += (left_bound - left_dist[k])
        elif right_dist[k] < left_dist[k]:
            right_bound = min(right_dist[r] for r in arr[k:])
            dists[k] = dist * right_bound
            dists[k - 1] += (right_bound - right_dist[k])
        elif left_dist[k] >= right_dist[k]:
            dists[k] = dist

